"use strict";
const shopLocations=['counter','bench','bus','quay'];
let nightShop={visited:[],calls:[],returned:false},shopPlace='',shopFeedback='';
try{const p=JSON.parse(localStorage.getItem(tideStoreKey)||'null')?.expansion?.shop;if(p){nightShop.visited=shopLocations.filter(k=>p.visited?.includes(k));nightShop.calls=['answer','ask','hang'].filter(k=>p.calls?.includes(k));nightShop.returned=p.returned===true;}}catch{}
const shopSaveBase=tideSave;
tideSave=function(){tideDeep.shop=nightShop;shopSaveBase();};
function shopVisit(id){if(!shopLocations.includes(id))return false;if(!nightShop.visited.includes(id))nightShop.visited.push(id);shopPlace=id;tideSave();return true;}
function shopCall(choice){if(!['answer','ask','hang'].includes(choice)||choice==='ask'&&!nightShop.calls.includes('answer'))return false;if(!nightShop.calls.includes(choice))nightShop.calls.push(choice);tideSave();return true;}
function shopMap(){return `<section class="night-shop"><header><small>原创虚构城市 / 雾江 / 2008</small><h2>旧巷手机修理铺</h2><p>你来替老板看一晚店。三部旧手机充着电，柜台上压着没填完的回访单。</p></header><nav class="shop-map" aria-label="雾江旧巷探索地图"><div class="shop-river">海堤 / 水道</div><div class="shop-street"></div>${[['counter','旧巷手机店','柜台与回访单'],['bench','维修工作台','旧手机与工具'],['bus','东站公交亭','末班车与留言'],['quay','旧海堤外侧','只到警示线外']].map(([id,title,sub])=>`<button class="map-${id}" data-shop-place="${id}"><b>${title}</b><span>${sub}</span>${nightShop.visited.includes(id)?'<small>来过</small>':''}</button>`).join('')}</nav>${shopPlace?shopPlaceMarkup():`<p class="shop-intro">街灯亮了又暗。玻璃门外没有人，门铃却晃了一下。你可以先把店里的东西看一遍。</p>`}<footer><button data-shop-phones>看看充电的手机</button><button data-shop-call="answer">${nightShop.visited.length>=2?'座机指示灯亮了 · 接听':'拿起柜台的座机'}</button><button data-shop-close>回到刚才的画面</button></footer><details><summary>关于这个场景</summary><p>这是虚构城市中的探索故事，地图不是现实导航。午夜时间、短信和电话均为游戏内事件，不拨打真实号码，不申请麦克风或通知权限，不自动响铃。当前可完整游玩的手机故事为潮声扩展篇；其他地点作为可探索场景和后续线索。</p></details></section>`;}
function shopPlaceMarkup(){const pages={counter:`<h3>玻璃柜台</h3><p>老板把“失物”两个字划掉，改成“待确认”。有的手机是客人送修的，有的是买来的，不是每一部都该交给第一个来问的人。</p><p>一张回访便条写着：“许同学，海边录音那部。号码打不通，先留着。”背面还有四个字：别催他回。</p><details><summary>填写这张回访单</summary>${shopFeedback?`<p role="status">${escapeHTML(shopFeedback)}</p>`:''}${nightShop.returned?'<p>已登记：暂存原件，等待核实归还。未把未知声音来源写成事实。</p>':`<form data-shop-return><label>这部手机的姓名<input name="name" aria-label="回访单姓名" maxlength="20"></label><label>记在便条上的爱好<select name="habit"><option value="">还不确定</option><option value="field">环境声音采集</option><option value="photo">毕业摄影</option><option value="band">乐队排练</option></select></label><button>先记入回访簿</button></form>`}</details>`,bench:`<h3>木头工作台</h3><p>银色6600的后盖贴着乐队贴纸，白色5230包在洗照片的信封里。黑色N73没有写名字，卡槽里还有一张存储卡。</p><p>这些手机里的年份不同，装的软件和常去的网页也不同。你把它们各放在一块旧鼠标垫上，避免装错后盖。</p><button data-shop-phones>给一部手机开机</button>`,bus:`<h3>东站公交亭</h3><p>末班车22:40，去老码头。雨把车窗上的广告泡皱了，只有四块钱的票价还清楚。</p><p>亭子的留言板上有人写：“那个人拿着录音机，一直没上车。”下面另一种笔迹回：“我看到的只有手机。”</p><button data-shop-place="counter">回到手机店</button>`,quay:`<h3>旧海堤外侧</h3><p>你停在警示线外。灯塔和检修口隔着很远，不应该把它们当作同一个地方。</p><p>门前的牌子写着S-04。风从水面吹上来，听不清敲击来自门后还是栏杆。你没有越过警示线。</p><p>店里的座机，在你记住这个牌子以后又亮了一次。</p><button data-shop-call="answer">查看店里留下的来电记录</button>`};return `<article class="shop-place">${pages[shopPlace]||''}</article>`;}
function shopCallMarkup(){return `<section class="night-shop"><header><small>午夜来电 / 剧情记录</small><h2>座机听筒</h2></header><article class="shop-place"><p>${nightShop.calls.includes('answer')?'听筒里先有一阵转轴声。随后，一个很近的声音说：“柜台底下的东西，不要跟手机放在一起。”':'你拿起听筒，里面没有拨号音。'}</p>${nightShop.calls.includes('ask')?'<p>你问他是谁。那边沉默了一会儿，传来你白天说过的半句话：“旧手机能修好吗？”</p><p>老板说他没有装通话录音。</p>':''}${nightShop.calls.includes('hang')?'<p>你放下了听筒。玻璃门外的街灯还亮着，指示灯熄了。你仍可以继续查看记录。</p>':''}</article><footer><button data-shop-call="ask">问他是谁</button><button data-shop-call="hang">放下听筒</button><button data-shop-map>回到店内地图</button></footer><small>无自动声音，电话只在游戏文字中发生。</small></section>`;}
function openShop(){dialog('雾江 / 旧巷手机修理铺',shopMap());}
const shopEntranceBase=renderPhoneEntrance,shopWorkbenchBase=renderWorkbench;
renderPhoneEntrance=function(){return `<section class="shop-entry"><small>夜班 / 手机与街巷的故事</small><h2>雾江市 · 旧巷手机店</h2><p>有些客人来修手机，有些只想取回以前留下的东西。</p><button data-shop-map>推开玻璃门</button></section>`+shopEntranceBase();};
renderWorkbench=function(){return `<button class="shop-map-entry" data-shop-map>雾江旧巷 / 场景地图</button>`+shopWorkbenchBase();};
document.addEventListener('click',e=>{const b=e.target.closest('[data-shop-map],[data-shop-place],[data-shop-phones],[data-shop-close],[data-shop-call]');if(!b)return;e.preventDefault();if(b.hasAttribute('data-shop-close'))return document.querySelector('#modal')?.close();if(b.hasAttribute('data-shop-phones'))return dialog('工作台上的旧手机',tideShelf());if(b.dataset.shopPlace){shopVisit(b.dataset.shopPlace);return openShop();}if(b.dataset.shopCall){shopCall(b.dataset.shopCall);return dialog('午夜来电 / 本机剧情',shopCallMarkup());}openShop();});
function shopReturn(name,habit){if(!tideDeep.talk.includes('hello')||!tide.seen.includes('qq'))return '这只是便条上的姓。还没有足够的记录，不能把两个人当成同一个人。';if(String(name||'').trim()!=='许舟'||habit!=='field')return '这和手机里的称呼或生活记录对不上。先留空也可以。';nightShop.returned=true;tideSave();return '回访单已登记。原件留在店里，不交给未经核实的来访者。';}
document.addEventListener('submit',e=>{if(!e.target.matches('[data-shop-return]'))return;e.preventDefault();const f=new FormData(e.target);shopFeedback=shopReturn(f.get('name'),f.get('habit'));openShop();document.querySelector('.shop-place details')?.setAttribute('open','');});
